// @control float speed "Animation Speed" [0.1, 5.0] = 1.0
uniform float speed;
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / u_resolution.xy;
  float v = sin(uv.x * 10.0 + u_time * speed) * cos(uv.y * 10.0 + u_time * speed);
  fragColor = vec4(0.1 + 0.1 * v, 0.2 + 0.2 * v, 0.4 + 0.3 * v, 1.0);
}
